function OverseaManageCustomerEventNode:OnBtnNodeClick()
    if self.data.status == EventStatus.Lock then
        GameUtils.Toast(localize("未触发该话题"))
    elseif self.data.status == EventStatus.NoGet then
        if not isNull(self.callBack) then
            self.callBack(self.index,self.data.eventId,self.npcId)
        end
    elseif self.data.status == EventStatus.HaveGet then
        self:ShowChapterReview()
    else
        printError("不存在的状态  status ==== %s",self.data.status)
    end
end

function OverseaManageCustomerEventNode:ShowChapterReview()
    local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
    local vo = MaidCoffeeUtils.GetGuestEventVo(self.data.eventId)
    if not isNull(vo) then
        local MaidCoffeeMgr = import('Game.MaidCoffee.MaidCoffeeMgr')
        local storyData = MaidCoffeeMgr:GetInstance():GetGuestChapterVos(vo.storyId)
        local record = {}
        for i, v in pairs(storyData) do
            local data = {}
            if table.count(v.choices) == 0 then
                data.owner = v:GetName()
                data.content = string.gsub(v.desc,"\\n","\n")
                table.insert(record,data)
            end
        end
        GameUtils.ShowChapterReview(record,nil,nil,function(go)
            CfUtils.SafeDelete(go.gameObject)
        end)
    end
end

